<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { api,ApiError,errorText } from '../api'
import { roles } from '../domain'
import type { Row } from '../domain'
import { ElMessage,ElMessageBox } from 'element-plus'
import { ShieldCheck,Check,LockKeyhole,RotateCcw } from 'lucide-vue-next'
const rows=ref<Row[]>([]),catalog=ref<Record<string,string>>({}),selected=ref(''),disabled=ref<string[]>([]),busy=ref(false),loading=ref(false),error=ref(''),needsTotp=ref(false),code=ref(''),query=ref('')
const row=computed(()=>rows.value.find(r=>r.role===selected.value)),supported=computed<string[]>(()=>row.value?.supported??Object.keys(catalog.value)),dirty=computed(()=>JSON.stringify([...disabled.value].sort())!==JSON.stringify([...(row.value?.disabled??[])].sort()))
const taskDependencies=['TASK_CREATE','TASK_UPDATE','ATTACHMENTS','COLLABORATION','REPORTS','KPI','NOTIFICATIONS','ORGANIZATION']
const groups=[{title:'任务与执行',description:'控制任务查看、办理与协作入口',keys:['TASK_VIEW','TASK_CREATE','TASK_UPDATE','ATTACHMENTS','COLLABORATION']},{title:'组织协作与分析',description:'保留公司、部门及本人职责范围',keys:['REPORTS','KPI','ORGANIZATION','NOTIFICATIONS']},{title:'系统管理',description:'管理组织配置、账号与操作记录',keys:['USER_ADMIN','ORG_ADMIN','RULE_ADMIN','CHANNEL_ADMIN','AUDIT']}]
const visibleGroups=computed(()=>groups.map(g=>({...g,keys:g.keys.filter(k=>catalog.value[k]&&catalog.value[k].includes(query.value.trim()))})).filter(g=>g.keys.length))
function dependency(key:string){return disabled.value.includes('TASK_VIEW')&&taskDependencies.includes(key)}
function effective(key:string){return supported.value.includes(key)&&!disabled.value.includes(key)&&!dependency(key)}
const count=computed(()=>supported.value.filter(effective).length)
async function load(){loading.value=true;error.value='';try{const data=await api.get('/admin/role-permissions');catalog.value=data.catalog;rows.value=data.roles;if(!selected.value)selected.value=rows.value[0]?.role??'';setRole(selected.value)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function setRole(role:string){selected.value=role;disabled.value=[...(rows.value.find(r=>r.role===role)?.disabled??[])];needsTotp.value=false;code.value='';error.value=''}
async function discard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('切换后将放弃尚未保存的权限调整。','放弃本次调整？',{confirmButtonText:'放弃调整',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function choose(role:string){if(role===selected.value)return;if(await discard())setRole(role)}
function toggle(key:string,value:unknown){if(!supported.value.includes(key)||dependency(key))return;if(value)disabled.value=disabled.value.filter(p=>p!==key);else if(!disabled.value.includes(key))disabled.value=[...disabled.value,key]}
async function save(){if(!row.value||busy.value||!dirty.value)return;try{await ElMessageBox.confirm(`将保存“${roles[selected.value]||selected.value}”的权限调整，当前生效 ${count.value} 项。该角色相关用户需要重新登录。`,'确认权限变更',{confirmButtonText:'保存权限',cancelButtonText:'继续编辑',type:'warning'})}catch{return}busy.value=true;error.value='';try{await api.put(`/admin/role-permissions/${selected.value}`,{version:row.value.version,disabled:disabled.value});ElMessage.success('权限已保存，相关用户需重新登录');await load()}catch(e){error.value=errorText(e);needsTotp.value=e instanceof ApiError&&e.code==='FRESH_TOTP_REQUIRED'}finally{busy.value=false}}
async function verify(){if(!/^\d{6}$/.test(code.value)){error.value='请输入六位动态验证码';return}busy.value=true;try{await api.post('/auth/totp/verify',{code:code.value});code.value='';needsTotp.value=false;error.value='';ElMessage.success('验证成功，请保存权限')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onBeforeRouteLeave(discard)
onMounted(load)
</script>
<template>
<section class="page-heading"><div><p class="eyebrow">ACCESS CONTROL</p><h1>角色权限配置</h1><p class="muted">按职责开放功能，组织与业务范围随岗位生效。</p></div><span class="scope-chip"><ShieldCheck :size="14"/>仅全局管理员可配置</span></section>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<div v-loading="loading" class="permission-layout">
 <aside class="panel role-picker"><p class="section-caption">选择角色</p><button v-for="r in rows" :key="r.role" class="role-option" :class="{active:selected===r.role}" :aria-pressed="selected===r.role" :disabled="busy" @click="choose(r.role)"><span>{{ r.role==='ADMIN'?'公司管理员':roles[r.role]||r.role }}</span><small>{{ (r.effective??[]).length }} 项生效</small></button><div class="fixed-role"><LockKeyhole :size="16"/><b>全局管理员</b><p>固定拥有全局管理与查看权限，不受此处开关影响。</p></div></aside>
 <section class="panel permission-editor">
<div class="permission-heading"><div><h2>{{ selected==='ADMIN'?'公司管理员':roles[selected]||selected }}</h2><p class="muted">{{ count }} / {{ supported.length }} 项功能生效<span v-if="dirty" class="unsaved-dot"> · 有未保存调整</span></p></div><el-input v-model="query" clearable placeholder="查找权限" aria-label="查找权限" style="max-width:220px"/></div>
 <p class="permission-note">开关可收紧此角色已有能力；“角色不支持”的项目无法启用。查看、办理及导出仍受公司、部门和任务状态限制。</p>
 <section v-for="g in visibleGroups" :key="g.title" class="permission-group"><h3>{{ g.title }}</h3><p class="muted">{{ g.description }}</p><div class="permission-options"><label v-for="key in g.keys" :key="key" class="permission-option" :class="{unsupported:!supported.includes(key)}"><span><b>{{ catalog[key] }}</b><small>{{ !supported.includes(key)?'角色不支持':dependency(key)?'需先启用“查看任务”':effective(key)?'已启用':'已关闭' }}</small></span><el-switch :model-value="effective(key)" :disabled="busy||!supported.includes(key)||dependency(key)" :aria-label="catalog[key]" @change="toggle(key,$event)"/></label></div></section>
 <el-empty v-if="!visibleGroups.length" description="未找到匹配权限" :image-size="60"/>
 <div v-if="needsTotp" class="verification"><h3>验证后保存</h3><p class="muted">请输入验证器中的六位动态验证码。</p><el-input v-model="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" aria-label="权限配置动态验证码"/><el-button :loading="busy" @click="verify">验证</el-button></div>
 <div class="permission-footer"><span class="muted">{{ dirty?'保存后，该角色用户需要重新登录':'当前配置已保存' }}</span><div class="action-strip"><el-button :disabled="!dirty||busy" @click="setRole(selected)"><RotateCcw :size="14"/>撤销调整</el-button><el-button type="primary" :loading="busy" :disabled="!row||!dirty||needsTotp" @click="save"><Check :size="14"/>保存权限</el-button></div></div>
 </section>
</div>
</template>
<style scoped>
.permission-layout{display:grid;grid-template-columns:232px minmax(0,1fr);gap:20px}.role-picker{align-self:start;padding:12px}.section-caption{font-size:12px;color:var(--muted);padding:4px 12px}.role-option{width:100%;display:flex;justify-content:space-between;align-items:center;gap:8px;padding:13px 12px;border:0;background:transparent;color:var(--text);border-radius:6px;font:inherit;text-align:left;cursor:pointer}.role-option small{font-size:11px;color:var(--muted)}.role-option:hover{background:var(--surface-hover)}.role-option.active{background:var(--accent-soft);color:var(--brand);font-weight:600}.role-option:focus-visible{outline:2px solid var(--brand)}.fixed-role{border-top:1px solid var(--line);margin-top:14px;padding:18px 12px 4px;color:var(--muted);font-size:12px}.fixed-role b{margin-left:6px}.fixed-role p{line-height:1.7}.permission-editor{padding:0;min-width:0}.permission-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:24px}.permission-heading h2{margin:0}.permission-heading p{margin:6px 0 0;font-size:12px}.permission-note{font-size:12px;color:var(--muted);margin:0;padding:0 24px 20px;border-bottom:1px solid var(--line)}.permission-group{padding:22px 24px;border-bottom:1px solid var(--line)}.permission-group h3{font-size:14px;margin:0}.permission-group>p{font-size:12px;margin:5px 0 18px}.permission-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 20px}.permission-option{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px;border:1px solid var(--line);border-radius:8px;min-width:0}.permission-option b{display:block;font-size:13px;font-weight:500}.permission-option small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.permission-option.unsupported{background:var(--surface-muted)}.permission-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 24px;flex-wrap:wrap}.permission-footer>span{font-size:12px}.verification{padding:24px;max-width:380px}.verification .el-button{margin-top:12px}.unsaved-dot{color:var(--warning)}@media(max-width:900px){.permission-layout{grid-template-columns:1fr}.role-picker{display:flex;flex-wrap:wrap;gap:4px}.role-option{width:auto;flex:1 1 150px}.section-caption{width:100%}.fixed-role{width:100%;padding:12px;margin:0}.fixed-role p{display:inline;margin-left:8px}.permission-options{grid-template-columns:1fr}}@media(max-width:600px){.permission-heading{align-items:stretch;flex-direction:column;padding:18px}.permission-group{padding:18px}.permission-note{padding:0 18px 18px}.permission-footer{padding:18px}.permission-footer .action-strip{width:100%}}
</style>
